package dev.industrialtechnology.railway;
import java.util.*;import net.minecraft.world.World;import net.minecraftforge.event.world.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;
public final class TrackWorld {
 private static final Map<World,Map<Long,List<TileTrack>>> buckets=new IdentityHashMap<>();private static final Map<World,Map<UUID,TileTrack>> loaded=new IdentityHashMap<>();private static final Map<World,Map<String,List<TileTrack>>> ends=new IdentityHashMap<>();
 private static String key(double[] p){return Math.round(p[0]*10)+":"+Math.round(p[1]*10)+":"+Math.round(p[2]*10);}
 public static void add(TileTrack t){World w=t.getWorldObj();if(w==null)return;Map<UUID,TileTrack> m=loaded.get(w);if(m==null){m=new HashMap<>();loaded.put(w,m);}m.put(t.id,t);ends.remove(w);buckets.remove(w);}
 public static void remove(TileTrack t){Map<UUID,TileTrack> m=loaded.get(t.getWorldObj());if(m!=null&&m.get(t.id)==t)m.remove(t.id);ends.remove(t.getWorldObj());buckets.remove(t.getWorldObj());}
 public static TileTrack get(World w,UUID id){Map<UUID,TileTrack> m=loaded.get(w);TileTrack t=m==null?null:m.get(id);return t==null||t.isInvalid()||!w.getChunkProvider().chunkExists(t.xCoord>>4,t.zCoord>>4)?null:t;}
 private static Map<String,List<TileTrack>> endpoints(World w){Map<String,List<TileTrack>> e=ends.get(w);if(e!=null)return e;e=new HashMap<>();Map<UUID,TileTrack> m=loaded.get(w);if(m!=null)for(TileTrack t:m.values()){for(int branch=0;branch<(t.shape==4?2:1);branch++){RailPath p=t.path(branch);for(double s:new double[]{0,p.length}){String k=key(p.point(s));List<TileTrack> list=e.get(k);if(list==null){list=new ArrayList<>();e.put(k,list);}if(!list.contains(t))list.add(t);}}}ends.put(w,e);return e;}
 public static Cursor nearest(World w,double x,double y,double z,double range){Set<TileTrack> near=new HashSet<>();Map<Long,List<TileTrack>> m=bucket(w);for(int cx=((int)Math.floor(x-range))>>4;cx<=((int)Math.floor(x+range))>>4;cx++)for(int cz=((int)Math.floor(z-range))>>4;cz<=((int)Math.floor(z+range))>>4;cz++){List<TileTrack> list=m.get((((long)cx)<<32)^(cz&0xffffffffL));if(list!=null)near.addAll(list);}Cursor best=null;double d=range*range;for(TileTrack t:near){RailPath p=t.path(t.active());double s=p.nearest(x,y,z),q=RailPath.distance(p.point(s),x,y,z);if(q<d){best=new Cursor(t.id,t.active(),s,1);d=q;}}return best;}
 private static Map<Long,List<TileTrack>> bucket(World w){Map<Long,List<TileTrack>> b=buckets.get(w);if(b!=null)return b;b=new HashMap<>();Map<UUID,TileTrack> m=loaded.get(w);if(m!=null)for(TileTrack t:m.values())for(int branch=0;branch<(t.shape==4?2:1);branch++){RailPath p=t.path(branch);for(double s=0;s<=p.length+.1;s+=1){double[] q=p.point(s);long key=(((long)((int)Math.floor(q[0])>>4))<<32)^(((int)Math.floor(q[2])>>4)&0xffffffffL);List<TileTrack> list=b.get(key);if(list==null){list=new ArrayList<>();b.put(key,list);}if(!list.contains(t))list.add(t);}}buckets.put(w,b);return b;}
 public static final class Cursor {
  public UUID track;public int branch,direction;public double s;public Cursor(UUID t,int b,double s,int d){track=t;branch=b;this.s=s;direction=d<0?-1:1;}public Cursor copy(){return new Cursor(track,branch,s,direction);}public RailPath path(World w){TileTrack t=get(w,track);return t==null?null:t.path(branch);}public double[] point(World w){RailPath p=path(w);return p==null?null:p.point(s);}public double yaw(World w){RailPath p=path(w);return p==null?0:p.yaw(s)+(direction<0?180:0);}
  public boolean move(World w,double distance){if(!Double.isFinite(distance)||Math.abs(distance)>2048)return false;Cursor c=copy();double remaining=distance;for(int hops=0;hops<128;hops++){RailPath p=c.path(w);if(p==null)return false;double target=c.s+remaining*c.direction;if(target>=0&&target<=p.length){c.s=target;track=c.track;branch=c.branch;s=c.s;direction=c.direction;return true;}boolean forward=target>p.length;double spill=forward?target-p.length:-target;double[] end=p.point(forward?p.length:0);List<TileTrack> candidates=endpoints(w).get(key(end));TileTrack chosen=null;int nextBranch=0,nextDir=1;if(candidates!=null)for(TileTrack t:candidates)if(!t.id.equals(c.track)){int b=t.active();RailPath np=t.path(b);if(RailPath.distance(np.point(0),end[0],end[1],end[2])<.02){chosen=t;nextBranch=b;nextDir=1;break;}if(RailPath.distance(np.point(np.length),end[0],end[1],end[2])<.02){chosen=t;nextBranch=b;nextDir=-1;break;}}if(chosen==null)return false;int travel=remaining>=0?1:-1;c.track=chosen.id;c.branch=nextBranch;c.direction=nextDir*travel;c.s=nextDir==1?0:chosen.path(nextBranch).length;remaining=spill*travel;}return false;}
 }
 @SubscribeEvent public void unload(WorldEvent.Unload e){loaded.remove(e.world);ends.remove(e.world);buckets.remove(e.world);}@SubscribeEvent public void chunk(ChunkEvent.Load e){for(Object o:e.getChunk().chunkTileEntityMap.values())if(o instanceof TileTrack)add((TileTrack)o);}@SubscribeEvent public void unchunk(ChunkEvent.Unload e){for(Object o:e.getChunk().chunkTileEntityMap.values())if(o instanceof TileTrack)remove((TileTrack)o);}public static void clear(){loaded.clear();ends.clear();buckets.clear();}
}
